  "Automatique (système)": { en: "Automatic (system)", de: "Automatisch (System)", es: "Automático (sistema)", pt: "Automático (sistema)", ru: "Автоматически (система)", ko: "자동 (시스템)", zhCN: "自动（系统）", zhTW: "自動（系統）" },
