  "Modèle": { en: "Model", de: "Modell", es: "Modelo", pt: "Modelo", ru: "Модель", ko: "모델", zhCN: "模型", zhTW: "模型" },
  "Valeurs utilisées quand les données du jeu ne disent rien.": { en: "Values used when the game data say nothing.", de: "Werte, wenn die Spieldaten nichts angeben.", es: "Valores usados cuando los datos del juego no dicen nada.", pt: "Valores usados quando os dados do jogo não dizem nada.", ru: "Значения, когда в данных игры ничего нет.", ko: "게임 데이터에 정보가 없을 때 쓰는 값.", zhCN: "游戏数据未提供时使用的值。", zhTW: "遊戲資料未提供時使用的值。" },
  "Algorithme": { en: "Algorithm", de: "Algorithmus", es: "Algoritmo", pt: "Algoritmo", ru: "Алгоритм", ko: "알고리즘", zhCN: "算法", zhTW: "演算法" },
  "Pour tester l'optimiseur : les valeurs par défaut sont les meilleures mesurées.": { en: "For testing the optimizer: the defaults are the best measured.", de: "Zum Testen des Optimierers: Die Standardwerte sind die besten gemessenen.", es: "Para probar el optimizador: los valores por defecto son los mejores medidos.", pt: "Para testar o otimizador: os valores padrão são os melhores medidos.", ru: "Для тестов оптимизатора: значения по умолчанию — лучшие из измеренных.", ko: "최적화 테스트용: 기본값이 측정상 가장 좋습니다.", zhCN: "用于测试优化器：默认值是实测最佳。", zhTW: "用於測試最佳化器：預設值是實測最佳。" },
  "Génération en cours": { en: "Generation in progress", de: "Berechnung läuft", es: "Generación en curso", pt: "Geração em andamento", ru: "Идёт расчёт", ko: "생성 중", zhCN: "正在生成", zhTW: "正在產生" },
  "{name} n'est pas de votre faction : tous les joueurs d'un guide de groupe sont de la même faction.": { en: "{name} is not of your faction: all the players of a group guide are of the same faction.", de: "{name} gehört nicht zu deiner Fraktion: Alle Spieler eines Gruppen-Guides gehören derselben Fraktion an.", es: "{name} no es de tu facción: todos los jugadores de una guía de grupo son de la misma facción.", pt: "{name} não é da sua facção: todos os jogadores de um guia de grupo são da mesma facção.", ru: "{name} не из вашей фракции: все игроки гайда для группы — одной фракции.", ko: "{name}은(는) 같은 진영이 아닙니다. 파티 가이드의 모든 플레이어는 같은 진영이어야 합니다.", zhCN: "{name} 与你不是同一阵营：队伍指南的所有玩家必须同阵营。", zhTW: "{name} 與你不是同一陣營：隊伍指南的所有玩家必須同陣營。" },
  "Un guide pour tout le groupe : la même route pour chacun, l'XP de chacun suivie, les quêtes déjà faites par certains reprises pour les autres. Chaque joueur doit être niveau 10 au moins (ou tous partir de la même zone), tous de la même faction.": { en: "One guide for the whole group: the same route for everyone, each player's XP followed, the quests some already did taken again for the others. Every player must be level 10 or more (or all start in the same zone), all of the same faction.", de: "Ein Guide für die ganze Gruppe: dieselbe Route für alle, die EP jedes Spielers verfolgt, von einigen schon erledigte Quests für die anderen erneut aufgenommen. Jeder Spieler muss mindestens Stufe 10 sein (oder alle starten in derselben Zone), alle derselben Fraktion.", es: "Una guía para todo el grupo: la misma ruta para todos, la XP de cada jugador seguida, las misiones que algunos ya hicieron se retoman para los demás. Cada jugador debe ser al menos de nivel 10 (o empezar todos en la misma zona), todos de la misma facción.", pt: "Um guia para o grupo todo: a mesma rota para todos, o XP de cada jogador acompanhado, as missões que alguns já fizeram retomadas para os outros. Cada jogador deve ter pelo menos nível 10 (ou todos começar na mesma zona), todos da mesma facção.", ru: "Один гайд для всей группы: один маршрут для всех, опыт каждого игрока учитывается, задания, уже выполненные некоторыми, берутся заново для остальных. Каждый игрок должен быть не ниже 10 уровня (или все начинают в одной зоне), все — одной фракции.", ko: "파티 전체를 위한 가이드: 모두 같은 경로, 각 플레이어의 경험치 추적, 일부가 이미 한 퀘스트는 다른 사람을 위해 다시 포함. 모든 플레이어는 10레벨 이상이어야 하며(또는 모두 같은 지역에서 시작), 같은 진영이어야 합니다.", zhCN: "整个队伍共用一份指南：每个人走同一路线，跟踪每位玩家的经验，部分人已完成的任务会为其他人重新安排。每位玩家须至少 10 级（或全部从同一区域开始），且同阵营。", zhTW: "整個隊伍共用一份指南：每個人走同一路線，追蹤每位玩家的經驗，部分人已完成的任務會為其他人重新安排。每位玩家須至少 10 級（或全部從同一區域開始），且同陣營。" },
  "{name} est niveau {n} : sous le niveau 10, tous les joueurs doivent partir de la même zone.": { en: "{name} is level {n}: below level 10, all the players must start in the same zone.", de: "{name} hat Stufe {n}: Unter Stufe 10 müssen alle Spieler in derselben Zone starten.", es: "{name} es de nivel {n}: por debajo del nivel 10, todos los jugadores deben empezar en la misma zona.", pt: "{name} é nível {n}: abaixo do nível 10, todos os jogadores devem começar na mesma zona.", ru: "{name} — уровень {n}: ниже 10 уровня все игроки должны начинать в одной зоне.", ko: "{name}은(는) {n}레벨입니다. 10레벨 미만이면 모든 플레이어가 같은 지역에서 시작해야 합니다.", zhCN: "{name} 为 {n} 级：10 级以下时，所有玩家必须从同一区域开始。", zhTW: "{name} 為 {n} 級：10 級以下時，所有玩家必須從同一區域開始。" },
  "Ajouter un joueur": { en: "Add a player", de: "Spieler hinzufügen", es: "Añadir un jugador", pt: "Adicionar um jogador", ru: "Добавить игрока", ko: "플레이어 추가", zhCN: "添加玩家", zhTW: "加入玩家" },
  "importé": { en: "imported", de: "importiert", es: "importado", pt: "importado", ru: "импортирован", ko: "가져옴", zhCN: "已导入", zhTW: "已匯入" },
