  "Dossier où exporter le pack Polestar": { en: "Folder to export the Polestar pack to", de: "Ordner für den Export des Polestar-Pakets", es: "Carpeta donde exportar el paquete de Polestar", pt: "Pasta para exportar o pacote do Polestar", ru: "Папка для экспорта пакета Polestar", ko: "Polestar 팩을 내보낼 폴더", zhCN: "导出 Polestar 包的文件夹", zhTW: "匯出 Polestar 包的資料夾" },
  "Guide exporté pour Polestar dans {path} : ouvrez ce dossier dans Planner ou Play de Polestar.": { en: "Guide exported for Polestar in {path}: open this folder in Polestar's Planner or Play.", de: "Guide für Polestar exportiert nach {path}: Öffne diesen Ordner in Planner oder Play von Polestar.", es: "Guía exportada para Polestar en {path}: abre esta carpeta en Planner o Play de Polestar.", pt: "Guia exportado para o Polestar em {path}: abra esta pasta no Planner ou no Play do Polestar.", ru: "Гайд экспортирован для Polestar в {path}: откройте эту папку в Planner или Play Polestar.", ko: "Polestar용 가이드를 {path}에 내보냈습니다. Polestar의 Planner나 Play에서 이 폴더를 여세요.", zhCN: "已为 Polestar 导出指南到 {path}：请在 Polestar 的 Planner 或 Play 中打开此文件夹。", zhTW: "已為 Polestar 匯出指南到 {path}：請在 Polestar 的 Planner 或 Play 中開啟此資料夾。" },
  "Guide « {name} » importé": { en: "Guide “{name}” imported", de: "Guide „{name}“ importiert", es: "Guía «{name}» importada", pt: "Guia “{name}” importado", ru: "Гайд «{name}» импортирован", ko: "'{name}' 가이드를 가져왔습니다", zhCN: "已导入指南“{name}”", zhTW: "已匯入指南「{name}」" },
  "Ajoute un guide reçu d'un autre joueur (fichier .fgguide)": { en: "Adds a guide received from another player (.fgguide file)", de: "Fügt einen von einem anderen Spieler erhaltenen Guide hinzu (.fgguide-Datei)", es: "Añade una guía recibida de otro jugador (archivo .fgguide)", pt: "Adiciona um guia recebido de outro jogador (arquivo .fgguide)", ru: "Добавляет гайд, полученный от другого игрока (файл .fgguide)", ko: "다른 플레이어에게 받은 가이드(.fgguide 파일)를 추가합니다", zhCN: "添加从其他玩家收到的指南（.fgguide 文件）", zhTW: "加入從其他玩家收到的指南（.fgguide 檔案）" },
  "Importer un guide…": { en: "Import a guide…", de: "Guide importieren…", es: "Importar una guía…", pt: "Importar um guia…", ru: "Импортировать гайд…", ko: "가이드 가져오기…", zhCN: "导入指南…", zhTW: "匯入指南…" },
  "Distance de découverte d'un lieu": { en: "Area discovery distance", de: "Entfernung zum Entdecken eines Gebiets", es: "Distancia de descubrimiento de un lugar", pt: "Distância de descoberta de um local", ru: "Дистанция открытия места", ko: "지역 발견 거리", zhCN: "地点发现距离", zhTW: "地點發現距離" },
  "XP d'exploration : un lieu est découvert en passant à cette distance de son centre.": { en: "Exploration XP: an area is discovered when passing within this distance of its center.", de: "Erkundungs-EP: Ein Gebiet gilt als entdeckt, wenn man so nah an seiner Mitte vorbeikommt.", es: "XP de exploración: un lugar se descubre al pasar a esta distancia de su centro.", pt: "XP de exploração: um local é descoberto ao passar a esta distância do centro.", ru: "Опыт за исследование: место открыто, если пройти на этом расстоянии от его центра.", ko: "탐험 경험치: 중심에서 이 거리 안으로 지나가면 지역을 발견합니다.", zhCN: "探索经验：从地点中心这么近的距离经过即视为发现。", zhTW: "探索經驗：從地點中心這麼近的距離經過即視為發現。" },
  "Nom du guide": { en: "Guide name", de: "Name des Guides", es: "Nombre de la guía", pt: "Nome do guia", ru: "Название гайда", ko: "가이드 이름", zhCN: "指南名称", zhTW: "指南名稱" },
  "ex. Duo nain guerrier et prêtre": { en: "e.g. Dwarf warrior and priest duo", de: "z. B. Duo Zwergenkrieger und Priester", es: "p. ej. Dúo enano guerrero y sacerdote", pt: "ex.: Dupla anão guerreiro e sacerdote", ru: "напр. Дуэт дворф-воин и жрец", ko: "예: 드워프 전사와 사제 2인", zhCN: "例如：矮人战士与牧师双人", zhTW: "例如：矮人戰士與牧師雙人" },
